<?php
/**
 * const.php — engine + default configuration for the EVEmu portal.
 *
 * DO NOT edit this file for settings: it is replaced on every update.
 * Put your own values in config.php (git-ignored); every define here is guarded
 * with if(!defined(...)) so config.php always wins. Helper functions and the
 * session bootstrap live here.
 */

