if (!defined('MAIL_ENCRYPTION')) define('MAIL_ENCRYPTION', 'tls'); // tls | ssl | none
if (!defined('MAIL_TIMEOUT'))    define('MAIL_TIMEOUT', 30);

// two-factor e-mail codes
if (!defined('TFA_ENABLED'))           define('TFA_ENABLED', true);
